drop index if exists public.cultivations_one_active_per_workspace_idx;
alter table public.cultivations add column cultivation_mode text not null default 'cycle' check(cultivation_mode in ('continuous','cycle')),add column current_stage public.lot_stage not null default 'vegetative',add column stage_started_on date,add column planned_end_date date;
update public.cultivations c set current_stage=coalesce((select l.stage from public.lots l where l.cultivation_id=c.id and l.active order by l.created_at limit 1),'vegetative'),stage_started_on=c.start_date,cultivation_mode=case when exists(select 1 from public.lots l where l.cultivation_id=c.id and l.stage='mother') then 'continuous' else 'cycle' end,planned_end_date=c.end_date;
alter table public.cultivations alter column stage_started_on set default current_date;
alter table public.cultivations alter column stage_started_on set not null;
alter table public.cultivations add constraint cultivations_planned_end_check check(planned_end_date is null or planned_end_date>=start_date);
create table public.cultivation_stage_history(id bigint generated always as identity primary key,workspace_id uuid not null references public.workspaces(id) on delete cascade,cultivation_id uuid not null references public.cultivations(id) on delete cascade,stage public.lot_stage not null,started_on date not null,ended_on date,changed_by uuid references auth.users(id) on delete set null default auth.uid(),created_at timestamptz not null default now(),check(ended_on is null or ended_on>=started_on));
create index cultivation_stage_history_timeline_idx on public.cultivation_stage_history(cultivation_id,started_on);
insert into public.cultivation_stage_history(workspace_id,cultivation_id,stage,started_on) select workspace_id,id,current_stage,stage_started_on from public.cultivations;
create or replace function public.track_cultivation_stage() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.current_stage is distinct from old.current_stage or new.stage_started_on is distinct from old.stage_started_on then if new.stage_started_on<old.stage_started_on then raise exception 'stage_date_before_previous_stage'; end if;update public.cultivation_stage_history set ended_on=new.stage_started_on-1 where cultivation_id=new.id and ended_on is null;insert into public.cultivation_stage_history(workspace_id,cultivation_id,stage,started_on,changed_by) values(new.workspace_id,new.id,new.current_stage,new.stage_started_on,(select auth.uid()));end if;return new;end;$$;
create trigger cultivations_track_stage after update of current_stage,stage_started_on on public.cultivations for each row execute function public.track_cultivation_stage();
alter table public.cultivation_stage_history enable row level security;alter table public.cultivation_stage_history force row level security;
revoke all on public.cultivation_stage_history from anon,authenticated;grant select on public.cultivation_stage_history to authenticated;
create policy cultivation_stage_history_select on public.cultivation_stage_history for select to authenticated using(public.is_workspace_member(workspace_id));
create or replace function public.activate_cultivation(p_workspace_id uuid,p_cultivation_id uuid) returns void language plpgsql security invoker set search_path='' as $$ begin if not public.can_edit_workspace(p_workspace_id) then raise exception 'workspace_write_forbidden'; end if;update public.cultivations set status='active',end_date=null where id=p_cultivation_id and workspace_id=p_workspace_id;if not found then raise exception 'cultivation_not_found';end if;end;$$;
revoke execute on function public.track_cultivation_stage() from public,anon,authenticated;revoke all on function public.activate_cultivation(uuid,uuid) from public,anon;grant execute on function public.activate_cultivation(uuid,uuid) to authenticated;
